// Unit tests for the PPTX exporter. Everything runs offline: image fetching is
// injected, and the generated archive is inspected with a tiny hand-rolled ZIP
// reader (node:zlib only) so we can prove the real slide XML contains our text.

import assert from 'node:assert/strict'
import test from 'node:test'
import zlib from 'node:zlib'

import { buildPptx, collectCitations } from '../../server/pptx.js'

/**
 * A real 160x90 PNG (patterned, ~43KB decoded). A 1x1 pixel would be smaller than
 * the decorative fallback's own XML, so it could not prove the image was embedded.
 */
const COVER_PNG_BASE64 =
  ''

const EOCD_SIG = 0x06054b50
const CENTRAL_SIG = 0x02014b50

/** Minimal ZIP reader: returns Map<entryName, Buffer> (real bytes, inflated). */
function readZip(buffer) {
  let eocd = -1
  for (let i = buffer.length - 22; i >= 0; i -= 1) {
    if (buffer.readUInt32LE(i) === EOCD_SIG) {
      eocd = i
      break
    }
  }
  assert.notEqual(eocd, -1, 'End Of Central Directory record not found')

  const count = buffer.readUInt16LE(eocd + 10)
  let offset = buffer.readUInt32LE(eocd + 16)
  const entries = new Map()

  for (let i = 0; i < count; i += 1) {
    assert.equal(buffer.readUInt32LE(offset), CENTRAL_SIG, `bad central directory header at ${offset}`)
    const method = buffer.readUInt16LE(offset + 10)
    const compressedSize = buffer.readUInt32LE(offset + 20)
    const nameLength = buffer.readUInt16LE(offset + 28)
    const extraLength = buffer.readUInt16LE(offset + 30)
    const commentLength = buffer.readUInt16LE(offset + 32)
    const localOffset = buffer.readUInt32LE(offset + 42)
    const name = buffer.toString('utf8', offset + 46, offset + 46 + nameLength)

    // Local header: 30 bytes with the same variable-length fields.
    assert.equal(buffer.readUInt32LE(localOffset), 0x04034b50, `bad local header for ${name}`)
    const localNameLength = buffer.readUInt16LE(localOffset + 26)
    const localExtraLength = buffer.readUInt16LE(localOffset + 28)
    const dataStart = localOffset + 30 + localNameLength + localExtraLength
    const raw = buffer.subarray(dataStart, dataStart + compressedSize)
    if (method === 0) entries.set(name, Buffer.from(raw))
    else if (method === 8) entries.set(name, zlib.inflateRawSync(raw))
    else assert.fail(`unsupported compression method ${method} for ${name}`)

    offset += 46 + nameLength + extraLength + commentLength
  }

  assert.equal(entries.size, count, 'every central-directory entry must be readable')
  return entries
}

const textOf = (zip, name) => {
  const entry = zip.get(name)
  assert.ok(entry, `${name} missing from the pptx archive`)
  return entry.toString('utf8')
}

/** XML-escape, so assertions match how pptxgenjs stores text. */
const xmlEscape = (text) =>
  text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')

const PALETTE = {
  bg: '#0B1F3A',
  bgAlt: '#12345F',
  fg: '#EAF2FF',
  muted: '#9DB4D6',
  accent: '#4FC3F7',
  accent2: '#FFB74D',
  surface: '#12294A',
  border: '#27476F',
}

const DESIGN = {
  styleName: '深海金融',
  rationale: '深色金融配色，强调数字与结论。',
  palette: PALETTE,
  typography: { heading: 'system-ui', body: 'system-ui', scale: 1, headingWeight: 700, letterSpacing: 0 },
  decor: { style: 'geometric', imageStyle: 'photo', radius: 14, pattern: 'grid' },
}

function fullDeck() {
  return {
    title: '演示文稿标题',
    meta: { model: 'deepseek-flash', generatedAt: '2026/9/12 15:00:00', citations: true },
    design: DESIGN,
    slides: [
      { index: 0, type: 'cover', title: '封面标题', subtitle: '一句概括', image: { prompt: 'ai', placement: 'background', url: '' } },
      { index: 1, type: 'bullets', title: '逐条要点', bullets: ['要点一', '要点二', '要点三'] },
      {
        index: 2,
        type: 'stats',
        title: '关键指标',
        stats: [
          { value: '2.9', unit: '天', label: '平均交付周期', delta: '-42%' },
          { value: '18', unit: '%', label: '转化率提升', delta: '+6pt' },
          { value: '4', unit: '项', label: '自动化流程' },
        ],
      },
      {
        index: 3,
        type: 'compare',
        title: '前后对比',
        compare: { left: { title: '现状', items: ['人工汇总', '口径不一'] }, right: { title: '改进后', items: ['自动汇总', '口径统一'] } },
      },
      { index: 4, type: 'timeline', title: '推进节奏', timeline: [{ label: 'Q1', title: '试点', text: '选择一个部门' }, { label: 'Q2', title: '推广', text: '覆盖全公司' }] },
      {
        index: 5,
        type: 'chart',
        title: '增长趋势',
        chart: { kind: 'bar', title: '月度增长', unit: '%', series: [{ name: '同比', data: [{ label: '一月', value: 12 }, { label: '二月', value: 18 }] }] },
      },
      { index: 6, type: 'table', title: '数据明细', table: { headers: ['列1', '列2'], rows: [['a', 'b'], ['c', 'd']] } },
      { index: 7, type: 'quote', title: '观点引用', quote: { text: '把复杂留给系统，把简单交给用户。', attribution: '张三 / CTO' }, notes: '讲慢一点' },
      {
        index: 8,
        type: 'references',
        title: '资料来源',
        citations: [{ n: 1, title: '来源标题', url: 'https://example.com/a', publisher: '示例出版社' }],
      },
    ],
  }
}

test('builds a real pptx with one slide per deck slide, titles present in slide XML', async () => {
  const deck = fullDeck()
  const buffer = await buildPptx({ deck })

  assert.ok(Buffer.isBuffer(buffer), 'buildPptx must resolve a Buffer')
  assert.equal(buffer.subarray(0, 2).toString('latin1'), 'PK', 'pptx must be a ZIP archive')
  assert.ok(buffer.length > 10_000, `expected > 10000 bytes, got ${buffer.length}`)

  const zip = readZip(buffer)
  for (let i = 1; i <= deck.slides.length; i += 1) {
    assert.ok(zip.has(`ppt/slides/slide${i}.xml`), `ppt/slides/slide${i}.xml must exist`)
  }
  assert.ok(!zip.has(`ppt/slides/slide${deck.slides.length + 1}.xml`), 'no extra slides may be emitted')

  deck.slides.forEach((slide, i) => {
    const xml = textOf(zip, `ppt/slides/slide${i + 1}.xml`)
    assert.ok(xml.includes(xmlEscape(slide.title)), `slide${i + 1}.xml must contain "${slide.title}"`)
  })
})

test('slide order is preserved and layout is 16:9 widescreen', async () => {
  const buffer = await buildPptx({ deck: fullDeck() })
  const zip = readZip(buffer)

  // pptxgenjs v4 renders LAYOUT_16x9 as 10in x 5.625in (9144000 x 5143500 EMU).
  const presentation = textOf(zip, 'ppt/presentation.xml')
  const size = /<p:sldSz[^>]*cx="(\d+)"[^>]*cy="(\d+)"/.exec(presentation)
  assert.ok(size, 'presentation.xml must declare a slide size')
  assert.equal(size[1], '9144000', 'widescreen width expected (10in)')
  assert.equal(size[2], '5143500', 'widescreen height expected (5.625in = 16:9)')
  assert.equal(Number(size[1]) / Number(size[2]), 16 / 9)

  // Every slide must be wired into the presentation, in deck order.
  const deckSlides = presentation
    .slice(presentation.indexOf('<p:sldIdLst>'), presentation.indexOf('</p:sldIdLst>'))
    .match(/<p:sldId /g)
  assert.equal(deckSlides?.length, 9, 'all nine slides must be referenced in order')

  const rels = textOf(zip, 'ppt/_rels/presentation.xml.rels')
  for (let i = 1; i <= 9; i += 1) {
    assert.ok(rels.includes(`slides/slide${i}.xml`), `presentation rels must point at slide${i}`)
  }
})

test('every type renders its own payload, plus citations and notes', async () => {
  const deck = fullDeck()
  const zip = readZip(await buildPptx({ deck }))

  // stats: value + label + delta
  const stats = textOf(zip, 'ppt/slides/slide3.xml')
  assert.ok(stats.includes('2.9'))
  assert.ok(stats.includes(xmlEscape('平均交付周期')))
  assert.ok(stats.includes('-42%'))

  // compare: both column headers
  const compare = textOf(zip, 'ppt/slides/slide4.xml')
  assert.ok(compare.includes(xmlEscape('现状')))
  assert.ok(compare.includes(xmlEscape('改进后')))

  // timeline labels
  const timeline = textOf(zip, 'ppt/slides/slide5.xml')
  assert.ok(timeline.includes('Q1'))
  assert.ok(timeline.includes(xmlEscape('试点')))

  // table: a real DrawingML table with header + body cells
  const table = textOf(zip, 'ppt/slides/slide7.xml')
  assert.match(table, /<a:tbl>/, 'table slide must contain a native pptx table')
  assert.ok(table.includes(xmlEscape('列1')))
  assert.ok(table.includes('>d<'), 'body cell text must be present')

  // quote + speaker notes (pptxgenjs names the notes part after the slide's 1-based position)
  const quote = textOf(zip, 'ppt/slides/slide8.xml')
  assert.ok(quote.includes(xmlEscape('把复杂留给系统，把简单交给用户。')))
  assert.ok(quote.includes(xmlEscape('张三 / CTO')))
  const notes = textOf(zip, 'ppt/notesSlides/notesSlide8.xml')
  assert.ok(notes.includes(xmlEscape('讲慢一点')), 'slide.notes must reach the speaker-notes part')

  // chart: a native chart part is created and referenced by the slide
  const chartRels = textOf(zip, 'ppt/slides/_rels/slide6.xml.rels')
  assert.match(chartRels, /charts\/chart\d+\.xml/, 'chart slide must reference an embedded chart part')
  const chartXml = [...zip.keys()].find((name) => /^ppt\/charts\/chart\d+\.xml$/.test(name))
  assert.ok(chartXml, 'a chart part must be embedded')
  assert.match(textOf(zip, chartXml), /barChart|lineChart|pieChart|doughnutChart/, 'chart part must hold a real chart')

  // references: this page's sources in small text at the bottom
  const references = textOf(zip, 'ppt/slides/slide9.xml')
  assert.ok(references.includes(xmlEscape('来源标题')))
  assert.ok(references.includes(xmlEscape('https://example.com/a')))

  // citations on a mid-deck slide are listed too
  const withCitations = {
    ...deck,
    slides: [{ index: 0, type: 'bullets', title: '带引用', bullets: ['a'], citations: [{ n: 1, title: '某来源', url: 'https://example.org/x' }] }],
  }
  const cited = textOf(readZip(await buildPptx({ deck: withCitations })), 'ppt/slides/slide1.xml')
  assert.ok(cited.includes(xmlEscape('某来源')))
  assert.ok(cited.includes(xmlEscape('https://example.org/x')))
})

test('apply the deck design (palette + typography) instead of hardcoded styling', async () => {
  const styled = await buildPptx({ deck: fullDeck() })
  const customDeck = fullDeck()
  customDeck.design = {
    palette: { ...PALETTE, accent: 'FF00AA', bg: '101010' },
    typography: { heading: 'Georgia', body: 'Verdana', scale: 1.1 },
  }
  const custom = await buildPptx({ deck: customDeck })

  const plain = readZip(styled)
  const themed = readZip(custom)
  const accent = (zip, name) => textOf(zip, name).includes('FF00AA')

  assert.ok(accent(themed, 'ppt/slides/slide1.xml'), 'custom accent must be used')
  assert.ok(!accent(plain, 'ppt/slides/slide1.xml'), 'default deck must not invent the custom accent')
  assert.ok(textOf(themed, 'ppt/slides/slide1.xml').includes('Georgia'), 'custom heading font must be used')
  assert.ok(textOf(themed, 'ppt/slides/slide2.xml').includes('Verdana'), 'custom body font must be used')
})

test('minimal deck without design, image, citations, notes or chart does not throw', async () => {
  const buffer = await buildPptx({ deck: { slides: [{ title: '只有标题' }] } })

  assert.ok(Buffer.isBuffer(buffer))
  assert.equal(buffer.subarray(0, 2).toString('latin1'), 'PK')
  const zip = readZip(buffer)
  const xml = textOf(zip, 'ppt/slides/slide1.xml')
  assert.ok(xml.includes(xmlEscape('只有标题')), 'the only title must be rendered')
  assert.match(xml, /<p:bg><p:bgPr><a:solidFill><a:srgbClr val="0B1F3A"\/>/, 'dark slate fallback background must be embedded')
})

test('an entirely empty or malformed deck still yields a valid file', async () => {
  for (const deck of [undefined, {}, { slides: null }, { slides: [null, 42, 'nope'] }]) {
    const buffer = await buildPptx({ deck })
    assert.ok(Buffer.isBuffer(buffer))
    assert.equal(buffer.subarray(0, 2).toString('latin1'), 'PK')
    readZip(buffer)
  }
})

test('a resolved image is embedded; a failed fetch still produces a valid file', async () => {
  const deck = {
    design: DESIGN,
    slides: [{ index: 0, type: 'cover', title: '带图封面', image: { url: 'https://img.test/a.png', placement: 'background' } }],
  }
  const png = Buffer.from(COVER_PNG_BASE64, 'base64')
  assert.equal(png.subarray(0, 8).toString('hex'), '89504e470d0a1a0a', 'fixture must be a real PNG')
  assert.ok(png.length > 20_000, 'fixture must be large enough to outweigh the fallback XML')

  const withImage = await buildPptx({ deck, fetchImage: async () => ({ buffer: png, mime: 'image/png' }) })
  const withoutImage = await buildPptx({ deck, fetchImage: async () => null })
  const rejecting = await buildPptx({
    deck,
    fetchImage: async () => {
      throw new Error('offline')
    },
  })

  const zip = readZip(withImage)
  // pptxgenjs renames embedded media (e.g. ppt/media/image-1-1.png): match the folder.
  const media = [...zip.keys()].filter((name) => /^ppt\/media\/.+\.png$/.test(name))
  assert.equal(media.length, 1, 'the fetched image must be embedded once in the archive')
  assert.ok(zip.get(media[0]).subarray(0, 8).equals(png.subarray(0, 8)), 'embedded bytes must be the fetched PNG')

  assert.ok(
    withImage.length > withoutImage.length,
    `embedded image (${withImage.length}) must grow the file vs fallback (${withoutImage.length})`,
  )
  assert.ok(
    withImage.length > rejecting.length,
    `embedded image (${withImage.length}) must grow the file vs rejected fetch (${rejecting.length})`,
  )
  for (const buffer of [withImage, withoutImage, rejecting]) {
    assert.equal(buffer.subarray(0, 2).toString('latin1'), 'PK')
  }
  // The cover must never end up blank: the fallback is a palette gradient.
  const fallbackXml = textOf(readZip(withoutImage), 'ppt/slides/slide1.xml')
  assert.match(fallbackXml, /gradFill|solidFill/, 'fallback decoration must use palette fills')
  assert.ok(fallbackXml.includes('12345F'), 'fallback gradient must use palette.bgAlt')
})

test('an unrecognised slide type falls back to bullets instead of being dropped', async () => {
  const deck = {
    design: DESIGN,
    slides: [
      { index: 0, type: 'mindmap', title: '未知类型页', bullets: ['仍然要点一'] },
      { index: 1, type: 'COVER', title: '大写类型页' },
    ],
  }
  const zip = readZip(await buildPptx({ deck }))
  assert.ok(zip.has('ppt/slides/slide1.xml'))
  assert.ok(zip.has('ppt/slides/slide2.xml'), 'both slides must survive')
  const xml = textOf(zip, 'ppt/slides/slide1.xml')
  assert.ok(xml.includes(xmlEscape('未知类型页')))
  assert.ok(xml.includes(xmlEscape('仍然要点一')), 'bullets must be rendered for the fallback type')
  assert.ok(textOf(zip, 'ppt/slides/slide2.xml').includes(xmlEscape('大写类型页')), 'type matching is case-insensitive')
})

test('chart with empty or malformed series does not throw and keeps a designed slide', async () => {
  const cases = [
    { index: 0, type: 'chart', title: '空图表' },
    { index: 1, type: 'chart', title: '坏系列', chart: { kind: 'bar', series: [] } },
    { index: 2, type: 'chart', title: '坏数据', chart: { series: [null, 'x', { name: 'a', data: 'nope' }] } },
    { index: 3, type: 'chart', title: '未知图形', chart: { kind: 'radar3d', series: [{ name: 'a', data: [{ label: '一', value: '1,2' }] }] } },
  ]
  const buffer = await buildPptx({ deck: { design: DESIGN, slides: cases } })
  const zip = readZip(buffer)
  cases.forEach((slide, i) => {
    const xml = textOf(zip, `ppt/slides/slide${i + 1}.xml`)
    assert.ok(xml.includes(xmlEscape(slide.title)), `slide${i + 1} must still be rendered`)
  })
  // A surviving chart still falls back to a bar chart rather than crashing.
  const rels = textOf(zip, 'ppt/slides/_rels/slide4.xml.rels')
  assert.match(rels, /charts\/chart\d+\.xml/)
})

test('collectCitations de-duplicates across the deck and never invents sources', () => {
  const entries = collectCitations({
    slides: [
      { citations: [{ n: 1, title: '甲', url: 'https://a.test' }] },
      { citations: [{ n: 9, title: '甲', url: 'https://a.test' }, { n: 2, title: '乙', url: 'https://b.test' }] },
      { citations: null },
    ],
  })
  assert.deepEqual(
    entries.map((entry) => entry.title),
    ['甲', '乙'],
  )
  assert.deepEqual(
    entries.map((entry) => entry.n),
    [1, 2],
  )
  assert.equal(collectCitations({}).length, 0)
})
